Step.Script:
                CREATE VIEW "${Company}_SYS_SP_GET_USER_PRIVILEGES" AS
                 	SELECT A.*, CAST(NULL AS VARCHAR) AS "Platform", B."Code" AS "UserCode"
                	FROM (
             	        SELECT CAST(NULL AS VARCHAR) AS "Source", CAST(NULL AS VARCHAR) AS "Target", CAST(NULL AS VARCHAR) AS "Value", CAST(NULL AS VARCHAR) AS "Automatic"                      
                ) A, (
	            	SELECT * 
	            	FROM "${Company}_SYS_USER" WHERE "Activated" = 'Y'
	            ) B;
